{
  "alert": {
    "kind": "sentry",
    "url": "https://sentry.io/organizations/acme/issues/12345/",
    "alert_id": "ACME-SHOP-12345",
    "observed_outcome": {"kind": "exception", "value": "ValidationError: amount must be positive (checkout/serializers.py)"},
    "side_effect": "an Order row is created before the serializer rejects the request",
    "reproducing_inputs": {"amount": 0.0, "locale": "tr_TR", "currency": "TRY", "cart_id": "c_8f3a"},
    "pii_substitutions": [{"field": "email", "shape": "same-domain synthetic address"}],
    "deterministic": true
  },
  "red_test": {
    "status": "committed",
    "path": "tests/regression/test_checkout_zero_amount.py",
    "commit": "a1b2c3d4e5f",
    "commit_message_has_alert_url": true,
    "asserts": ["response.status_code == 422", "'amount must be positive' in response.json()['detail']"],
    "side_effect_asserts": ["Order.objects.filter(cart_id='c_8f3a').count() == 0"],
    "red_ci_run_url": "https://github.com/acme/shop/actions/runs/76",
    "failure_matches_alert": true,
    "stable_runs": 3
  },
  "fix": {
    "pr_url": "https://github.com/acme/shop/pull/9981",
    "first_fix_commit": "b2c3d4e5f6a",
    "diff_lines": 18,
    "touches_red_test_assertions": false,
    "hotfix": false
  },
  "verification": {
    "ci_run_url": "https://github.com/acme/shop/actions/runs/77",
    "passed": true,
    "skipped_or_xfail": false
  },
  "owner": "swe:alice",
  "review": {
    "merged_at": "2026-05-24",
    "next_review_at": "2026-08-22",
    "alert_resolved": true,
    "outcome": {"reviewed_at": "2026-08-22", "regression_events_in_window": 0, "same_signature_new_issue": false}
  }
}

